import Foundation
public struct ExtractedItem: Codable, Equatable, Sendable { public var title: String?; public var category: LifeCategory?; public var amount: Decimal?; public var currency: String?; public var date: Date?; public var recurring: Recurrence?; public var reminderOffsets: [Int]?; public var confidence: Double }
public struct NaturalLanguageParser: Sendable { public init() {} ; static func simpleDate(in lower: String, now: Date) -> Date? { let months=["january":1,"february":2,"march":3,"april":4,"may":5,"june":6,"july":7,"august":8,"september":9,"october":10,"november":11,"december":12]; let parts=lower.split{ !$0.isLetter && !$0.isNumber }.map(String.init); for (i,p) in parts.enumerated() { if let m=months[p], i+1 < parts.count, let day=Int(parts[i+1]) { var c=Calendar.current.dateComponents([.year], from: now); c.month=m; c.day=day; let candidate=Calendar.current.date(from:c); if let d=candidate, d < now { c.year=(c.year ?? 2026)+1; return Calendar.current.date(from:c) }; return candidate }; if let y=Int(p), y > 1900, y < 2200 { return Calendar.current.date(from: DateComponents(year:y, month:12, day:31)) } }; return nil } ; public func parse(_ text: String, now: Date = Date()) -> ExtractedItem { let lower=text.lowercased(); let category: LifeCategory = lower.contains("insurance") ? .insurance : lower.contains("passport") ? .travel : lower.contains("netflix") ? .subscriptions : lower.contains("warranty") ? .warranties : .other; let title = lower.contains("car insurance") ? "Car Insurance" : lower.contains("passport") ? "Passport" : text.split(separator:" ").prefix(4).joined(separator:" "); let currency = lower.contains("€") ? "EUR" : lower.contains("$") ? "USD" : nil; let amount = text.replacingOccurrences(of: ",", with: "").split(separator:" ").compactMap { Decimal(string: $0.filter{"0123456789.".contains($0)}) }.first; let recurrence: Recurrence = lower.contains("every year") || lower.contains("yearly") || lower.contains("annual") || lower.contains("renews every") ? .yearly : lower.contains("every month") || lower.contains("monthly") ? .monthly : lower.contains("six months") ? .everySixMonths : .none; let date = Self.simpleDate(in: lower, now: now); return ExtractedItem(title: title.isEmpty ? nil : title, category: category, amount: amount, currency: currency, date: date, recurring: recurrence, reminderOffsets: category == .travel ? [90,30,7,1] : [30], confidence: date == nil ? 0.55 : 0.86) } }
public struct AIJSONValidator { public init() {} ; public func decode(_ data: Data) throws -> ExtractedItem { let dec=JSONDecoder(); dec.dateDecodingStrategy = .iso8601; let item = try dec.decode(ExtractedItem.self, from: data); if item.confidence < 0 || item.confidence > 1 { throw LifeAdminError.invalidJSON }; return item } }
public enum AIProcessingMode: String, Codable, CaseIterable { case askEveryTime, allowAutomatically, disabled }
public protocol AIExtracting: Sendable { func extract(from text: String) async throws -> ExtractedItem }
public typealias GeminiExtractionClient = ProxyAIClient
